        var queries = addGroup("Parameters", parameters.size(), uri.buildUpon().query(null));
        for (var i = 0; i < parameters.size(); i++) {
            // generate same url but without this parameter (keeping the others as-is, encoded)
            var newQuery = new StringBuilder();
            for (var j = 0; j < parameters.size(); j++) {
                if (i == j) continue;
                if (newQuery.length() > 0) newQuery.append("&");
                newQuery.append(parameters.get(j)[0]);
                // a parameter without '=' must keep having no '='
                if (parameters.get(j)[1] != null) newQuery.append("=").append(parameters.get(j)[1]);
            }
            var builder = uri.buildUpon()
                    .encodedQuery(newQuery.length() == 0 ? null : newQuery.toString());

            // append the parameter (decoded, just for displaying)
            addPart(decode(parameters.get(i)[0]), decode(parameters.get(i)[1]), queries, builder);
        }
    }

    // fragment
    if (uri.getFragment() != null) {
        var fragment = addGroup("Fragment", -1, uri.buildUpon().fragment(null));
        addPart("#", uri.getFragment(), fragment, null);
    }

    setVisibility(box.getChildCount() > 0);
}

/**
 * Splits an encoded query ("foo=bar&baz") into its encoded parameters ([["foo","bar"],["baz",null]]).
 * The parts are kept encoded, so that the original url can be rebuilt without modifying them.
 * A null value means the parameter had no '=' at all.
 */
private static List<String[]> parseEncodedQuery(String encodedQuery) {
    var parameters = new ArrayList<String[]>();
    if (encodedQuery == null || encodedQuery.isEmpty()) return parameters;

    for (var parameter : encodedQuery.split("&")) {
        if (parameter.isEmpty()) continue;
        var separator = parameter.indexOf('=');
        if (separator == -1) parameters.add(new String[]{parameter, null});
        else parameters.add(new String[]{
                parameter.substring(0, separator),
                parameter.substring(separator + 1)
        });
    }
    return parameters;
}

/**
 * Decodes an encoded url part (utf-8, and '+' as space), for displaying purposes.
 * Note that it is decoded just once (%2525 -> %25)
 */
private static String decode(String encoded) {
    if (encoded == null) return "";
    try {
        return Uri.decode(encoded.replace("+", " "));
    } catch (Exception ignored) {
        // can't decode, return as-is
        return encoded;
    }
}

